from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/move_out')
def move_out():
    reasons = list(request.args.get('reasons', ''))

    template = '''
    <h1>Reasons for moving out</h1>
    <p>{}</p>
    '''.format('<br>'.join(reasons))

    return render_template_string(template)

if __name__ == '__main__':
    app.run()
